$files = Get-ChildItem -Path ".\servisler" -Filter *.ini -Recurse | Where-Object { $_.FullName -notlike "*\servisler\yedek\*" }

foreach ($file in $files) {
    $content = [System.IO.File]::ReadAllBytes($file.FullName)
    $encoding = New-Object System.Text.UTF8Encoding($true) # BOM destekli UTF8

    # Dosyayı string olarak oku (BOM'u korumak için byte bazlı işlem veya doğru encoding ile okuma gerekir)
    # Ancak en güvenli yol, dosyayı orijinal haliyle okuyup satırları işlemek ve yapıyı bozmamaktır.

    $lines = [System.IO.File]::ReadAllLines($file.FullName, [System.Text.Encoding]::Default) # Windows varsayılanı genelde ANSI/UTF8'dir
    # Daha garantisi: Dosyayı byte olarak okuyup UTF-8 BOM kontrolü yapmak ve satırları ayırmak.

    $rawContent = [System.IO.File]::ReadAllText($file.FullName, [System.Text.Encoding]::GetEncoding("utf-8"))
    # Not: PowerShell'de ReadAllText bazen BOM'u okur ama yazarken dikkatli olmak gerekir.
    # En sağlam yöntem: Dosyayı satır satır oku, bölüm takibi yap ve sadece ilgili satırı değiştir.

    $allLines = [System.IO.File]::ReadAllLines($file.FullName)
    $newLines = @()
    $currentSection = ""
    $changed = $false

    for ($i = 0; $i -lt $allLines.Count; $i++) {
        $line = $allLines[$i]
        $trimmedLine = $line.Trim()

        # Bölüm kontrolü (case-insensitive)
        if ($trimmedLine -match '^\[(.+)\]$') {
            $currentSection = $matches[1].ToLower()
            $newLines += $line
            continue
        }

        # [veritabani] bölümündeysek ve port satırıysa
        if ($currentSection -eq "veritabani" -and $trimmedLine -match '^port\s*=\s*5432\s*$') {
            # Boşlukları korumak için regex ile yakalayalım: 'port' + '=' etrafındaki boşluklar
            if ($line -match '^(\s*port\s*=\s*)5432(\s*)$') {
                $newLines += $matches[1] + "6543" + $matches[2]
                $changed = $true
            } else {
                $newLines += $line
            }
        } else {
            $newLines += $line
        }
    }

    if ($changed) {
        # Dosyayı orijinal encoding ve satır sonu ile yazmak için:
        # Önce dosyanın BOM'una bakalım
        $bytes = [System.IO.File]::ReadAllBytes($file.FullName)
        $hasBom = $false
        if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
            $hasBom = $true
        }

        $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
        if ($hasBom) {
            $bom = [System.Text.Encoding]::UTF8.GetPreamble()
            [System.IO.File]::WriteAllBytes($file.FullName, $bytes) # Bu zaten var olanı yazar
            # Doğru yöntem: BOM ile birlikte yazmak
            $contentToWrite = [System.Text.Encoding]::UTF8.GetString([System.Text.Encoding]::Convert($utf8NoBom, [System.Text.Encoding]::Default).GetBytes($rawContent)) # Karmaşıklaşmasın
        }

        # Basit ve etkili yöntem: 
        # Dosyayı okurken UTF8 (BOM dahil) olarak oku, değiştir ve aynı şekilde yaz.
        $originalLines = [System.IO.File]::ReadAllLines($file.FullName, [System.Text.Encoding]::GetEncoding("utf-8"))
        # Yukarıda $newLines zaten oluşturuldu.

        # Dosyayı orijinal encoding ile tekrar yazalım. 
        # Windows'ta ReadAllLines genellikle UTF8/ANSI okur. 
        # En güvenli yol: dosyayı byte olarak değil, string array olarak alıp, 
        # BOM varsa onu koruyarak yazmak.

        $encoding = [System.Text.Encoding]::GetEncoding("utf-8")
        [System.IO.File]::WriteAllLines($file.FullName, $newLines, $encoding)
        Write-Host "Updated: $($file.FullName)"
    }
}

